/* WEB-002 首屏。礼盒素材嵌入文件末尾，不依赖 CDN 或外部字体。 */
body { background: var(--gw-color-bg); font-family: var(--gw-font-family); }
::selection { background: var(--gw-color-accent); color: var(--gw-color-surface); }
:focus-visible { outline: var(--gw-focus-width) solid var(--gw-focus-color); outline-offset: var(--gw-focus-offset); }
.skip-link { position: fixed; left: 16px; top: 8px; padding: 12px 16px; min-height: 44px; z-index: var(--gw-z-skip); transform: translateY(-160%); }
.skip-link:focus { top: 8px; transform: none; }
.site-header { z-index: var(--gw-z-sticky); background: var(--gw-color-bg); border: 0; backdrop-filter: none; }
.site-header__inner { max-width: calc(var(--gw-layout-max) + 2 * var(--gw-layout-gutter)); padding: 8px var(--gw-layout-gutter); min-height: 72px; gap: 24px; flex-wrap: nowrap; }
.brand { gap: 24px; font-family: var(--gw-font-family-brand); font-size: 18px; font-weight: 700; letter-spacing: .13em; min-height: 48px; }
.brand svg { width: 36px; height: 36px; }
.site-nav { display: flex; gap: 32px; margin-left: auto; }
.site-nav a { display: inline-flex; align-items: center; min-height: 48px; font-size: 16px; color: var(--gw-color-text); text-underline-offset: 6px; white-space: nowrap; }
.site-nav a:hover { text-decoration: underline; text-decoration-color: var(--gw-color-accent); }
.site-nav a:active { color: var(--gw-color-accent); }
.site-header .btn { min-height: 48px; margin-left: 16px; padding: 8px 24px; border: 0; border-radius: var(--gw-radius-pill); background: var(--gw-button-bg); color: var(--gw-button-text); font-family: inherit; font-size: 16px; white-space: nowrap; }
.mode-flag { padding: 4px 10px; font-size: 12px; line-height: 1.5; letter-spacing: 0; font-weight: 600; color: var(--gw-color-warning); background: var(--gw-color-warning-bg); border: 1px solid #dbc7a5; }
.mode-flag--real { background: var(--gw-color-success-bg); color: var(--gw-color-success); border-color: var(--gw-color-success); }
.gw-hero { position: relative; isolation: isolate; max-width: 1672px; min-height: min(50vw, 760px); margin: 0 auto; padding: 0; background: var(--gw-color-bg); }
.gw-hero__art { position: absolute; z-index: -1; inset: 80px 32px auto auto; width: min(846px, calc((100svh - 180px) * 1.51)); max-width: 100%; height: clamp(306px, calc((100svh - 180px) * .85), 476px); background-image: var(--gw-hero-image); background-position: center bottom; background-size: contain; background-repeat: no-repeat; }
.gw-hero__content { position: relative; width: 53%; padding: 24px 0 64px; margin-left: max(var(--gw-layout-gutter), calc((100% - var(--gw-layout-max)) / 2)); }
.gw-hero h1 { margin: 0; font-size: clamp(72px, 6.7vw, 112px); font-weight: var(--gw-font-weight-display); line-height: 1.12; letter-spacing: -.04em; color: #000; }
.gw-hero .hero__sub { margin: 24px 0 0; max-width: none; font-size: clamp(28px, 2.65vw, 44px); font-weight: 400; line-height: 1.35; letter-spacing: -.025em; color: var(--gw-color-text); }
.gw-hero__description { margin: 24px 0 0; font-size: var(--gw-font-size-lg); line-height: 1.6; color: var(--gw-color-text-secondary); }
.gw-hero .hero__cta { margin-top: 32px; }
.gw-button { display: inline-flex; align-items: center; justify-content: center; gap: 24px; min-height: var(--gw-button-height); padding: 16px var(--gw-button-padding-x); border: 0; border-radius: var(--gw-button-radius); background: var(--gw-button-bg); color: var(--gw-button-text); font-family: inherit; font-size: 20px; font-weight: 500; line-height: 1.5; cursor: pointer; }
.gw-button svg { flex-shrink: 0; }
.gw-button, .site-header .btn { transition: background-color var(--gw-motion-duration) var(--gw-motion-ease), color var(--gw-motion-duration) var(--gw-motion-ease); }
@media (hover: hover) { .gw-button:hover, .site-header .btn:hover { background: var(--gw-color-primary-hover); color: var(--gw-button-text); } }
.gw-button:active, .site-header .btn:active { background: var(--gw-color-primary-active); color: var(--gw-button-text); }
.gw-button:disabled, .site-header .btn:disabled { background: var(--gw-color-disabled); color: var(--gw-color-text-secondary); cursor: not-allowed; opacity: 1; }
.gw-hero__bottom { position: absolute; bottom: 0; left: 0; right: 0; display: flex; align-items: center; justify-content: space-between; gap: 32px; padding: 8px var(--gw-layout-gutter); }
.gw-scroll-link { min-width: 44px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; color: var(--gw-color-text-secondary); text-decoration: none; }
.gw-scroll-link:hover { color: var(--gw-color-text); text-decoration: underline; }
.gw-scroll-link:active { color: var(--gw-color-accent); }
.gw-hero .hero__flag { max-width: 34ch; margin: 16px 0 0; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--gw-color-text-secondary); font-size: 12px; line-height: 1.5; font-weight: 400; }
.gw-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.gw-hero [hidden] { display: none; }
#view, #how { scroll-margin-top: 120px; }
.gw-on-landing #actions { visibility: hidden; pointer-events: none; }
@media (min-width: 1024px) {
  .gw-hero__art { transform: scale(1.13); transform-origin: right top; }
}
@media (max-width: 1199px) {
  .site-nav { gap: 16px; }
  .site-header__inner { gap: 16px; }
  .brand { gap: 12px; font-size: 16px; }
  .site-header .btn { margin-left: 0; }
  .site-nav a { font-size: 14px; }
  .gw-hero { min-height: 680px; }
  .gw-hero__art { width: min(665px, calc((100svh - 180px) * 1.51)); right: 8px; height: clamp(306px, calc((100svh - 180px) * .85), 374px); }
  .gw-hero__content { width: 60%; }
  .gw-hero h1 { font-size: 80px; }
}
@media (max-width: 1023px) {
  .site-header__inner { flex-wrap: wrap; gap: 8px 16px; }
  .site-nav { display: none; }
  .brand { margin-right: auto; }
  .site-header .btn { margin-left: auto; }
  .gw-hero { min-height: 0; display: flex; flex-direction: column; }
  .gw-hero__content { order: 0; width: calc(100% - 2 * var(--gw-layout-gutter)); padding-top: 24px; padding-bottom: 0; }
  .gw-hero h1 { font-size: var(--gw-font-size-h1); }
  .gw-hero .hero__sub { font-size: 32px; }
  .gw-hero__description { font-size: 18px; }
  .gw-hero__art { position: relative; order: 1; z-index: var(--gw-z-base); inset: auto; width: 100%; height: auto; aspect-ratio: 1672 / 941; margin: 24px 0 0; background-size: contain; background-position: center; }
  .gw-hero__bottom { position: static; order: 2; gap: 16px; }
  .gw-hero .hero__flag { max-width: 40ch; }
}
@media (max-width: 599px) {
  .site-header__inner { padding: 4px var(--gw-layout-gutter); min-height: 88px; }
  .brand { gap: 12px; font-size: 15px; min-height: 44px; }
  .brand svg { width: 32px; height: 32px; }
  .mode-flag { order: 3; flex-basis: auto; margin: 0 0 4px; }
  .site-header .btn { min-height: 44px; padding: 8px 16px; font-size: 13px; }
  .gw-hero__content { padding-top: 16px; }
  .gw-hero h1 { font-size: var(--gw-font-size-h1); letter-spacing: -.04em; line-height: 1.15; }
  .gw-hero .hero__sub { margin-top: 24px; font-size: 26px; }
  .gw-hero__description { margin-top: 16px; font-size: 16px; }
  .gw-hero .hero__cta { margin-top: 24px; }
  .gw-button { min-height: 56px; padding: 12px 24px; font-size: 18px; gap: 24px; }
  .gw-hero__bottom { align-items: flex-start; gap: 8px; flex-direction: column; padding-bottom: 8px; }
  .gw-hero .hero__flag { max-width: 100%; font-size: 12px; }
  #view, #how { scroll-margin-top: 128px; }
}
@media (max-width: 359px) {
  .site-header__inner { gap: 4px 8px; }
  .brand { gap: 8px; font-size: 13px; }
  .site-header .btn { padding-inline: 12px; }
  .gw-hero h1 { font-size: 46px; }
}
@media (prefers-reduced-motion: no-preference) {
  .gw-hero__content { animation: gw-arrive 240ms var(--gw-motion-ease) both; }
  @keyframes gw-arrive { from { transform: translateY(8px); } to { transform: translateY(0); } }
}

/* 第二屏：文字在上，三只礼盒与自然铺开的缎带在下。 */
.gw-how { max-width: calc(var(--gw-layout-max) + 2 * var(--gw-layout-gutter)); margin: 0 auto; padding: 40px var(--gw-layout-gutter) 48px; min-height: calc(100svh - 72px); }
.gw-how__heading { display: flex; justify-content: space-between; align-items: flex-end; gap: 48px; margin-bottom: 48px; }
.gw-how__heading h2 { margin: 0; font-size: var(--gw-font-size-h2); font-weight: var(--gw-font-weight-bold); line-height: var(--gw-font-line-height-tight); letter-spacing: -.03em; }
.gw-how__heading > p { margin: 0 0 8px; font-size: var(--gw-font-size-lg); line-height: var(--gw-font-line-height-body); color: var(--gw-color-text-secondary); }
.gw-how__steps { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; padding: 0; margin: 0; list-style: none; }
.gw-how__step { min-width: 0; display: flex; flex-direction: column; }
.gw-how__copy { padding-inline: 8px; min-height: 184px; }
.gw-how__number { display: flex; align-items: center; gap: 16px; color: var(--gw-color-accent); font-size: 14px; font-weight: 600; line-height: 1.5; font-variant-numeric: tabular-nums; }
.gw-how__number span { color: var(--gw-color-text-secondary); font-size: 12px; letter-spacing: .06em; }
.gw-how__step:nth-child(2) .gw-how__number { color: var(--gw-color-accent-blue); }
.gw-how__copy h3 { margin: 16px 0; font-size: clamp(23px, 2vw, 30px); font-weight: 600; line-height: var(--gw-font-line-height-heading); letter-spacing: -.03em; }
.gw-how__copy > p { margin: 0; color: var(--gw-color-text-secondary); font-size: 16px; line-height: var(--gw-font-line-height-body); }
.gw-how__copy .gw-how__detail { margin-top: 16px; font-size: 13px; }
.gw-how__target { display: inline-block; padding: 2px 8px; margin-right: 4px; border: 1px solid var(--gw-color-border); border-radius: var(--gw-radius-pill); color: var(--gw-color-warning); background: var(--gw-color-warning-bg); font-size: 12px; line-height: 1.5; }
.gw-how__gift { aspect-ratio: 1.35; width: 100%; background-image: var(--gw-how-image); background-size: 300% auto; background-repeat: no-repeat; }
.gw-how__gift--red { background-position: left center; }
.gw-how__gift--blue { background-position: center center; }
.gw-how__gift--card { background-position: right center; }
.gw-how__closing { display: flex; justify-content: space-between; gap: 24px; margin: 32px 8px 0; padding-top: 24px; border-top: 1px solid var(--gw-color-border); font-size: 16px; color: var(--gw-color-text); }
.gw-how__closing span { color: var(--gw-color-text-secondary); font-size: 12px; }
@media (min-width: 1024px) {
  .gw-how { max-width: 1200px; min-height: 0; padding: 40px 48px 56px; }
  .gw-how__heading { align-items: center; gap: 32px; margin-bottom: 40px; }
  .gw-how__heading h2 { font-size: 40px; font-weight: 600; }
  .gw-how__heading > p { margin: 0; font-size: 16px; }
  .gw-how__steps { gap: 0; }
  .gw-how__copy { min-height: 176px; padding-inline: 0; text-align: center; }
  .gw-how__number { justify-content: center; font-size: 12px; }
  .gw-how__copy h3 { margin: 16px 0 12px; font-size: 22px; font-weight: 600; }
  .gw-how__copy > p { font-size: 14px; }
  .gw-how__copy .gw-how__detail { margin-top: 12px; font-size: 12px; }
  .gw-how__gift { align-self: center; }
  .gw-how__closing { margin-inline: 0; font-size: 14px; }
}
@media (min-width: 768px) and (max-width: 1023px) {
  .gw-how { padding-top: 40px; }
  .gw-how__heading { gap: 32px; margin-bottom: 48px; }
  .gw-how__heading > p { font-size: 16px; }
  .gw-how__copy { min-height: 232px; padding-inline: 0; }
  .gw-how__copy h3 { font-size: 22px; }
  .gw-how__copy > p { font-size: 14px; }
  .gw-how__copy br { display: none; }
  .gw-how__copy .gw-how__detail { font-size: 12px; }
}
@media (max-width: 767px) {
  .gw-how { padding-top: 32px; padding-bottom: 48px; min-height: 0; }
  .gw-how__heading { display: block; margin-bottom: 32px; }
  .gw-how__heading > p { margin-top: 24px; font-size: 16px; }
  .gw-how__heading h2 span { display: block; }
  .gw-how__steps { grid-template-columns: 1fr; gap: 0; }
  .gw-how__step { display: grid; grid-template-columns: 28px minmax(0, 1fr) 88px; gap: 8px 12px; align-items: start; padding: 32px 0; border-bottom: 1px solid var(--gw-color-border); }
  .gw-how__step:first-child { padding-top: 0; }
  .gw-how__step:last-child { border-bottom: 0; }
  .gw-how__copy { display: contents; }
  .gw-how__number { grid-column: 1; grid-row: 1; justify-content: center; width: 28px; height: 28px; border: 1px solid var(--gw-color-border); border-radius: var(--gw-radius-pill); font-size: 11px; }
  .gw-how__number span { display: none; }
  .gw-how__copy h3 { grid-column: 2; grid-row: 1; margin: 3px 0 0; font-size: 18px; line-height: 1.4; }
  .gw-how__copy > p { grid-column: 2; grid-row: 2; font-size: 13px; }
  .gw-how__copy br { display: none; }
  .gw-how__copy .gw-how__detail { grid-row: 3; margin-top: 0; font-size: 12px; }
  .gw-how__gift { grid-column: 3; grid-row: 1 / 4; align-self: center; aspect-ratio: 1.2; background-image: var(--gw-how-closed-image); background-size: 300% auto; }
  .gw-how__closing { flex-direction: column; gap: 8px; margin-inline: 0; }
}

/* 内置 imagegen 重制，2026-10-30；单盒单色缎带修正版。 */
:root { --gw-hero-image: url('data:image/webp;base64,'); }

/* 第二屏透明礼盒：桌面打开，手机闭合；内置 imagegen，2026-10-30。 */
:root { --gw-how-image: url('data:image/webp;base64,'); --gw-how-closed-image: url('data:image/webp;base64,'); }
